  "Force enable zoom": {"res": "Chrome:force_enable_zoom_title", "hu": "Nagyítás/kicsinyítés kényszerített engedélyezése", "de": "Zoom zwingend aktivieren", "fr": "Forcer l'activation du zoom", "es": "Forzar zoom"},
  "Force enable zoom summary": {"res": "Chrome:force_enable_zoom_summary", "hu": "Webhely nagyításelutasítási kérelmének felülbírálata", "de": "Website-Anfrage zum Verhindern des Vergrößerns übergehen", "fr": "Ignorer la demande d'un site refusant de faire un zoom avant", "es": "Ignorar la solicitud de un sitio web para no acercar la imagen", "en": "Override a website's request to prevent zooming in"},
