  "Preload webpages": {"res": "Chrome:prefetch_bandwidth_title", "hu": "Weboldalak előtöltése", "de": "Webseiten vorab laden", "fr": "Précharger les pages Web", "es": "Cargar páginas web previamente"},
  "Preview": {"res": "Chrome:font_size_preview", "hu": "Előnézet", "de": "Vorschau", "fr": "Aperçu", "es": "Obtener vista previa"},
  "Reduce data usage": {"res": "Chrome:reduce_data_usage_title", "hu": "Adatfelhasználás csökkentése", "de": "Datennutzung reduzieren", "fr": "Réduire la consommation des données", "es": "Reducir uso de datos"},
  "Reduce data usage description": {"res": "Chrome:reduce_data_usage_description", "hu": "Ha a funkció engedélyezve van, a Google optimalizálja a felkeresett oldalakat az adathasználat csökkentése érdekében.", "de": "Wenn diese Funktion aktiviert ist, werden von Ihnen besuchte Seiten von Google optimiert, um die Datennutzung zu reduzieren.", "fr": "Si cette fonctionnalité est activée, nous optimisons les pages que vous consultez afin de réduire la consommation des données.", "es": "Cuando esta función está activada, Google optimiza las páginas que visitas para reducir el uso de datos.", "en": "When this feature is turned on, pages you visit will be optimized by Google to reduce your data usage."},
  "Reset translate settings": {"res": "Chrome:reset_translate_defaults", "hu": "A fordító beállításainak visszaállítása", "de": "Übersetzungseinstellungen zurücksetzen", "fr": "Réinitialiser les paramètres de Google Traduction", "es": "Restablecer ajustes de traducción"},
  "Safe Browsing description": {"res": "Chrome:safe_browsing_description", "hu": "A Chrome Biztonságos Böngészés funkciója figyeli a kártékony oldalakat, és megvéd az adathalászattól, a rosszindulatú programoktól és a káros letöltésektől.", "de": "Das Safe Browsing-System von Chrome erkennt außerdem schädliche Seiten und schützt Sie vor Phishing, Malware und schädlichen Downloads.", "fr": "Nous utilisons également le système de navigation sécurisée de Google Chrome pour détecter les pages nuisibles tout en vous protégeant du phishing, des logiciels malveillants et des téléchargements dangereux.", "es": "El sistema de navegación segura de Chrome también se utilizará para detectar páginas maliciosas y para proteger al usuario de la suplantación de identidad, del software malicioso y de las descargas peligrosas.", "en": "Chrome's Safe Browsing system will also be used to detect malicious pages and protect you from phishing, malware, and harmful downloads."},
  "Translate description": {"res": "Chrome:translate_prefs_description", "hu": "Ha a funkció be van kapcsolva, a Chrome felajánlja az idegen nyelven írt oldalak fordítását a Google Fordítóval.", "de": "Wenn diese Funktion aktiviert ist, bietet Chrome eine Übersetzung von Seiten in anderen Sprachen durch Google Übersetzer an.", "fr": "Si cette fonctionnalité est activée, Google Chrome vous propose de traduire les pages rédigées dans d'autres langues à l'aide de Google Traduction.", "es": "Cuando esta función está activada, Chrome ofrece la posibilidad de traducir páginas escritas en otros idiomas mediante el Traductor de Google.", "en": "When this feature is turned on, Chrome will offer to translate pages written in other languages using Google Translate."},
  "Website settings": {"res": "Chrome:category_website_settings", "hu": "Webhelybeállítások", "de": "Website-Einstellungen", "fr": "Paramètres des sites Web", "es": "Ajustes del sitio web"},
  "You have no saved website settings.": {"res": "Chrome:no_saved_website_settings", "hu": "Nincsenek elmentett webhelybeállítások.", "de": "Sie haben keine Website-Einstellungen gespeichert.", "fr": "Vous n'avez enregistré aucun paramètre de site Web.", "es": "No tienes ajustes del sitio web guardados."},
  "Your translate settings have been reset.": {"res": "Chrome:translate_prefs_toast_description", "hu": "A fordító beállításai visszaálltak.", "de": "Ihre Übersetzungseinstellungen wurden zurückgesetzt.", "fr": "Vos préférences Google Traduction ont été réinitialisées.", "es": "Se han restablecido tus preferencias de traducción.", "en": "Your translate preferences have been reset."},
  "Font size preview text": {"res": "Chrome:font_size_preview_text_alt4", "hu": "Húzza a csúszkát, amíg kényelmesen nem tudja olvasni a szöveget; legalább ekkorának kell lennie, miután duplán koppint a bekezdésre.", "de": "Ziehen Sie den Schieberegler, bis Sie diesen Text problemlos lesen können. Nach dem Doppeltippen auf einen Abschnitt sollte der Text mindestens so groß sein.", "fr": "Faites glisser le curseur pour lire le texte aisément. Sa taille doit être similaire à celle-ci lorsque vous appuyez deux fois sur un paragraphe.", "es": "Arrastra el control deslizante hasta que puedas leer cómodamente. El texto debe tener al menos este tamaño después de tocar un párrafo dos veces.", "en": "Drag the slider until you can read this comfortably. Text should look at least this big after double-tapping on a paragraph."},
  "Text scaling": {"res": "Chrome:font_size_alt1", "hu": "Szöveg nagyítása", "de": "Text-Skalierung", "fr": "Mise à l'échelle texte", "es": "Ajuste de texto"},
  "Learn More": {"res": "Chrome:do_not_track_learn", "hu": "További információ", "de": "Weitere Informationen", "fr": "En savoir plus", "es": "Más información"},
