  "cp.rem.9": {"res": "CalendarGoogle:@array/preferences_default_reminder_labels:9", "hu": "45 perc", "de": "45 Minuten", "fr": "45 minutes", "es": "45 minutos", "en": "45 minutes"},
  "cp.rem.10": {"res": "CalendarGoogle:@array/preferences_default_reminder_labels:10", "hu": "1 óra", "de": "1 Stunde", "fr": "1 heure", "es": "1 hora", "en": "1 hour"},
  "cp.rem.11": {"res": "CalendarGoogle:@array/preferences_default_reminder_labels:11", "hu": "2 óra", "de": "2 Stunden", "fr": "2 heures", "es": "2 horas", "en": "2 hours"},
  "cp.rem.12": {"res": "CalendarGoogle:@array/preferences_default_reminder_labels:12", "hu": "3 óra", "de": "3 Stunden", "fr": "3 heures", "es": "3 horas", "en": "3 hours"},
  "cp.rem.13": {"res": "CalendarGoogle:@array/preferences_default_reminder_labels:13", "hu": "12 óra", "de": "12 Stunden", "fr": "12 heures", "es": "12 horas", "en": "12 hours"},
  "cp.rem.14": {"res": "CalendarGoogle:@array/preferences_default_reminder_labels:14", "hu": "24 óra", "de": "24 Stunden", "fr": "24 heures", "es": "24 horas", "en": "24 hours"},
