  "cp.quick.0": {"res": "CalendarGoogle:@array/quick_response_defaults:0", "hu": "Csak pár percet késik.", "de": "Bin einige Minuten verspätet", "fr": "Désolé, j'aurai quelques minutes de retard.", "es": "Llego un par de minutos tarde", "en": "Running just a couple of minutes late."},
  "cp.quick.1": {"res": "CalendarGoogle:@array/quick_response_defaults:1", "hu": "Legyen ott körülbelül 10 perc alatt.", "de": "Bin in etwa 10 Minuten da", "fr": "Désolé, j'arrive dans 10 minutes environ.", "es": "Llegaré en unos diez minutos", "en": "Be there in about 10 minutes."},
  "cp.quick.2": {"res": "CalendarGoogle:@array/quick_response_defaults:2", "hu": "Kezdjék el nélkülem.", "de": "Fangt ohne mich an", "fr": "Commencez sans moi.", "es": "Empezad sin mí", "en": "Go ahead and start without me."},
  "cp.quick.3": {"res": "CalendarGoogle:@array/quick_response_defaults:3", "hu": "Sajnálom, nem érek oda. Kénytelenek leszünk átütemezni.", "de": "Schaffe es leider nicht. Neuen Termin ausmachen?", "fr": "Désolé, je ne peux pas venir. Nous allons devoir reporter.", "es": "No puedo, mejor en otro momento", "en": "Sorry, I can't make it. We'll have to reschedule."}
